// Qualitative material streamlines around the current loaded sail geometry.
// These visual tracers reuse local pressure/separation, without feeding forces back.
import {V,clamp} from './constants.js';
import {boatScale} from './boats.js';
import {sailPoint} from './sail-geometry.js';
import {stampGeometryState} from './geometry-state.js';
import {loadedForceState} from './force-data.js';
import {sailFlow,sailFlowAtHeight} from './sail-flow.js';
import {samplePressure,sampleSailFlow} from './pressure-solver.js';
const mix=(a,b,t)=>V.add(V.mul(a,1-t),V.mul(b,t));
function finish(points,weights,meta={}){const distances=[0];for(let i=1;i<points.length;i++)distances.push(distances[i-1]+V.length(V.sub(points[i],points[i-1])));return{points,weights,distances,length:distances.at(-1),...meta};}
// Coarse visual contact mesh. Segment tests keep a downstream sail from being
// crossed by a streamline exiting another sail; contact redirects it along the face.
function contactMesh(fields,sample){const mesh=[],N=14,M=10;for(const field of fields){const grid=Array.from({length:M+1},(_,j)=>Array.from({length:N+1},(_,i)=>sample(field.type,j/M,i/N)));for(let j=0;j<M;j++)for(let i=0;i<N;i++)for(const points of [[grid[j][i],grid[j+1][i],grid[j][i+1]],[grid[j][i+1],grid[j+1][i],grid[j+1][i+1]]]){const [a,b,c]=points,e1=V.sub(b,a),e2=V.sub(c,a);mesh.push({a,e1,e2,n:V.unit(V.cross(e1,e2)),tangent:V.unit(V.sub(grid[j][i+1],grid[j][i])),lo:[0,1,2].map(k=>Math.min(a[k],b[k],c[k])),hi:[0,1,2].map(k=>Math.max(a[k],b[k],c[k])),separation:samplePressure(field,(j+.5)/M,(i+.5)/N).separation});}}return mesh;}
function firstContact(a,b,mesh){const d=V.sub(b,a),lo=a.map((v,i)=>Math.min(v,b[i])),hi=a.map((v,i)=>Math.max(v,b[i]));let found=null;for(const triangle of mesh){if(triangle.lo[0]>hi[0]+1e-7||triangle.lo[1]>hi[1]+1e-7||triangle.lo[2]>hi[2]+1e-7||triangle.hi[0]<lo[0]-1e-7||triangle.hi[1]<lo[1]-1e-7||triangle.hi[2]<lo[2]-1e-7)continue;const p=V.cross(d,triangle.e2),det=V.dot(triangle.e1,p);if(Math.abs(det)<1e-10)continue;const q=V.sub(a,triangle.a),u=V.dot(q,p)/det;if(u<0||u>1)continue;const cross=V.cross(q,triangle.e1),v=V.dot(d,cross)/det;if(v<0||u+v>1)continue;const t=V.dot(triangle.e2,cross)/det;if(t>1e-5&&t<.99999&&(!found||t<found.t))found={t,triangle,point:V.add(a,V.mul(d,t))};}return found;}
function avoidContacts(path,mesh,k){for(let i=1;i<path.points.length;i++){const start=path.points[i-1];let target=path.points[i],hit;for(let n=0;n<8&&(hit=firstContact(start,target,mesh));n++){const normal=hit.triangle.n,side=V.dot(V.sub(start,hit.point),normal)>=0?1:-1,travel=V.sub(target,start);let tangent=V.sub(travel,V.mul(normal,V.dot(travel,normal)));if(V.length(tangent)<.01)tangent=hit.triangle.tangent;target=V.add(V.add(hit.point,V.mul(normal,side*.22*k)),V.mul(V.unit(tangent),Math.min(.28*k,V.length(travel)*(1-hit.t))));path.weights[i]=Math.max(path.weights[i],hit.triangle.separation*.7);}path.points[i]=firstContact(start,target,mesh)?start:target;}const {points,weights,distances,length,...meta}=path;return finish(points,weights,meta);}
export function buildWindPaths(state,metric,count,{sampleSurface,time=0}={}){
 const loaded=stampGeometryState(loadedForceState(state,metric)),k=boatScale(state),sample=sampleSurface||((type,h,u)=>V.mul(sailPoint(type,h,u,loaded),k)),headFlow=sailFlow(state,metric.speed),headAws=Math.max(.1,headFlow.aws),fields=metric.sails||[],ambient=fields.length?Math.max(2,Math.floor(count/4)):count,paths=[],sections=new Map();
 for(let i=0;i<count;i++){
  if(i<ambient){const cross=(i%2?1:-1)*(8+6*Math.floor(i/2)/Math.max(1,Math.ceil(ambient/2)-1))*k,height=(i%2?10:2)*k,local=sailFlowAtHeight(state,height,metric.speed),flow=local.direction,across=[-flow[2],0,flow[0]],start=V.add(V.mul(flow,-18*k),V.mul(across,cross)),points=Array.from({length:19},(_,j)=>V.add(V.add(start,V.mul(flow,j*2*k)),[0,height,0]));paths.push(finish(points,points.map(()=>0),{ambient:true,speed:local.aws/headAws,windHeight:height,aws:local.aws,flow}));continue;}
  const slot=i-ambient,field=fields[slot%fields.length],cycle=Math.floor(slot/fields.length),side=cycle%2?-1:1,rows=Math.max(1,Math.ceil((count-ambient)/(fields.length*2))),h=.25+.58*(rows===1?.5:Math.floor(cycle/2)/(rows-1)),type=field.type,windHeight=sample(type,h,.5)[1],local=sampleSailFlow(field,h,sailFlowAtHeight(state,windHeight,metric.speed)),flow=local.direction,across=[-flow[2],0,flow[0]],probe=samplePressure(field,h,.5),separation=clamp(Math.max(probe.separation,probe.luff*.7)),chord=V.sub(sample(type,h,1),sample(type,h,0)),reverse=V.dot(chord,flow)<0;
  const sectionKey=type+':'+h+':'+reverse;let section=sections.get(sectionKey);if(!section){const base=[],normals=[];for(let j=0;j<=24;j++){const u=reverse?1-j/24:j/24,du=V.sub(sample(type,h,Math.min(1,u+.003)),sample(type,h,Math.max(0,u-.003))),dv=V.sub(sample(type,Math.min(.99,h+.003),u),sample(type,Math.max(.01,h-.003),u)),normal=V.unit(V.cross(du,dv));if(normals.length&&V.dot(normals.at(-1),normal)<0)for(let n=0;n<3;n++)normal[n]*=-1;normals.push(normal);base.push(sample(type,h,u));}section={base,normals};sections.set(sectionKey,section);}const skin=section.base.map((point,j)=>V.add(point,V.mul(section.normals[j],side*(.13+.035*separation)*k)));

  const entry=skin[0],tangent=V.unit(V.sub(skin[1],entry)),lead=V.sub(entry,V.mul(tangent,2.2*k)),start=V.sub(lead,V.mul(flow,7*k)),points=[],weights=[];
  for(let j=0;j<7;j++){points.push(mix(start,lead,j/7));weights.push(0);}for(let j=0;j<6;j++){points.push(mix(lead,entry,j/6));weights.push(0);}points.push(...skin);weights.push(...skin.map(()=>0));
  const end=skin.at(-1),exit=V.unit(V.sub(end,skin.at(-2)));for(let j=1;j<=28;j++){const d=j/28*9*k,blend=1-Math.exp(-d/(1.5*k)),direction=V.unit(mix(exit,flow,blend)),spread=(.015+separation*.3)*(1-Math.exp(-d/k))*k,phase=time*1.4-d/k*2.6+h*11+side;points.push(V.add(V.add(end,V.mul(direction,d)),V.add(V.mul(across,spread*Math.sin(phase)),[0,spread*.65*Math.cos(phase*.86),0])));weights.push(separation*clamp(d/(2*k)));}
  paths.push(finish(points,weights,{type,h,side,separation,windHeight,aws:local.aws,flow,speed:local.aws/headAws*clamp(1+.18*Math.abs(probe.cp)-.25*separation,.65,1.7)}));
 }
 const mesh=contactMesh(fields,sample);return paths.map(path=>avoidContacts(path,mesh,k));
}
export function sampleWindPath(path,distance){const d=((distance%path.length)+path.length)%path.length;let lo=0,hi=path.distances.length-1;while(hi-lo>1){const m=(lo+hi)>>1;if(path.distances[m]<d)lo=m;else hi=m;}const t=(d-path.distances[lo])/Math.max(1e-8,path.distances[hi]-path.distances[lo]);return{point:mix(path.points[lo],path.points[hi],t),turbulence:path.weights[lo]*(1-t)+path.weights[hi]*t,age:d/path.length,fade:clamp(Math.min(d,path.length-d)/(1.5))};}
